import 'package:flutter/material.dart';

const paydaySlogan = 'Plan today, enjoy tomorrow.';

const paydayEmerald=Color(0xff0E5A47),paydaySaffron=Color(0xffF4A62A),paydaySand=Color(0xffFBF6EA);
class PaydayMark extends StatelessWidget{
 const PaydayMark({super.key,this.size=48});
 final double size;
 @override Widget build(BuildContext context)=>Semantics(image:true,label:'Payday',
  child:SizedBox.square(dimension:size,child:CustomPaint(painter:const _MarkPainter())));
}
class _MarkPainter extends CustomPainter{
 const _MarkPainter();
 @override void paint(Canvas c,Size size){
  c.scale(size.width/100,size.height/100);
  c.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(0,0,100,100),const Radius.circular(26)),Paint()..color=paydayEmerald);
  final p=Paint()..color=paydaySand;
  c.drawRect(const Rect.fromLTWH(25,19,16,62),p);
  c.drawPath(Path()..moveTo(25,19)..lineTo(53,19)..cubicTo(85,19,85,63,53,63)..lineTo(25,63)..close(),p);
  c.drawCircle(const Offset(52,41),7,Paint()..color=paydayEmerald);
  c.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(44,70,26,11),const Radius.circular(6)),Paint()..color=paydaySaffron);
 }
 @override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;
}
class PaydayBrand extends StatelessWidget{
 const PaydayBrand({super.key,this.compact=false});
 final bool compact;
 @override Widget build(BuildContext context)=>Semantics(label:'PAYDAY. $paydaySlogan',
  child:ExcludeSemantics(child:Row(mainAxisSize:MainAxisSize.min,children:[
   PaydayMark(size:compact?35:42),const SizedBox(width:10),
   Text('Payday',style:TextStyle(fontFamily:'Bricolage',fontWeight:FontWeight.w800,fontSize:compact?25:30,
    color:Theme.of(context).brightness==Brightness.dark?paydaySand:paydayEmerald)),
  ])));
}

const paydayIconBase64 = '';
